/// Validate typed owner before entering the lower planner and require its entire
/// computed pattern mapping at return. This performs no legacy owned conversion.
/// The lower adapter owns/admit/releases its plan/cache allocations via ctx.ledger.
pub fn plan_production_definition<'src>(
    planner: &mut dyn DefinitionPlanner,
    ctx: &mut DefinitionContext<'src, '_>,
    kind: DefinitionKind,
    element: ElementId,
    owner: DefinitionOwner,
    transform: Affine,
    bounds: [f64; 4],
    style: &CssPaint<'src>,
    control: &mut dyn WorkControl,
) -> Result<ProductionDefinitionPlan<'src>> {
    validate_production_plan(ctx, kind, element, owner, transform, bounds, style, control,
        |ctx, control| planner.plan_owned_definition(ctx, kind, element, owner, transform, bounds, style, control))
}

/// Nonpattern dispatch through the same combined operations object supplied to
/// `ChannelAwareProductionDecodeSession::step`. Pattern is rejected here so a
/// decoder cannot fall back to the compatibility planner without a channel.
pub fn plan_channel_aware_definition<'src>(
    planner: &mut dyn ChannelAwareProductionDecodeOperations,
    ctx: &mut DefinitionContext<'src, '_>,
    kind: DefinitionKind,
    element: ElementId,
    owner: DefinitionOwner,
    transform: Affine,
    bounds: [f64; 4],
    style: &CssPaint<'src>,
    control: &mut dyn WorkControl,
) -> Result<ProductionDefinitionPlan<'src>> {
    if kind == DefinitionKind::Pattern {
        return Err(invalid(0));
    }
    validate_production_plan(ctx, kind, element, owner, transform, bounds, style, control,
        |ctx, control| planner.plan_owned_definition(ctx, kind, element, owner, transform, bounds, style, control))
}

/// Required channel-aware production route for patterns. All source, owner,
/// style, bounds, returned descriptor/mapping, and post validation is shared
/// with the compatibility production entry point above.
pub fn plan_production_pattern<'src>(
    planner: &mut dyn PaintChannelDefinitionPlanner,
    ctx: &mut DefinitionContext<'src, '_>,
    element: ElementId,
    owner: DefinitionOwner,
    channel: PaintChannel,
    transform: Affine,
    bounds: [f64; 4],
    style: &CssPaint<'src>,
    control: &mut dyn WorkControl,
) -> Result<ProductionDefinitionPlan<'src>> {
    validate_production_plan(ctx, DefinitionKind::Pattern, element, owner, transform, bounds, style, control,
        |ctx, control| planner.plan_owned_pattern_definition(ctx, element, owner, channel, transform, bounds, style, control))
}

/// Pattern dispatch through a combined decoder operations object. The explicit
/// channel is mandatory and no compatibility planner is consulted.
pub fn plan_channel_aware_pattern<'src>(
    planner: &mut dyn ChannelAwareProductionDecodeOperations,
    ctx: &mut DefinitionContext<'src, '_>,
    element: ElementId,
    owner: DefinitionOwner,
    channel: PaintChannel,
    transform: Affine,
    bounds: [f64; 4],
    style: &CssPaint<'src>,
    control: &mut dyn WorkControl,
) -> Result<ProductionDefinitionPlan<'src>> {
    validate_production_plan(ctx, DefinitionKind::Pattern, element, owner, transform, bounds, style, control,
        |ctx, control| planner.plan_owned_pattern_definition(ctx, element, owner, channel, transform, bounds, style, control))
}

fn validate_production_plan<'src>(
    ctx: &mut DefinitionContext<'src, '_>,
    kind: DefinitionKind,
    element: ElementId,
    owner: DefinitionOwner,
    transform: Affine,
    bounds: [f64; 4],
    style: &CssPaint<'src>,
    control: &mut dyn WorkControl,
    plan: impl FnOnce(&mut DefinitionContext<'src, '_>, &mut dyn WorkControl) -> Result<ProductionDefinitionPlan<'src>>,
) -> Result<ProductionDefinitionPlan<'src>> {
    owner.validate(ctx)?;
    validate_style(ctx.shared.source(), style, control)?;
    ctx.shared
        .element(element, crate::memory::add(element.0, 1)?, control)?;
    // The canonical owner anchors planning/target scope; `element` independently
    // identifies the resolved definition (for example a URL on a host path).
    if !vexel_geometry::affine_valid(transform)
        || !bounds.into_iter().all(f64::is_finite)
        || bounds[2] < 0.
        || bounds[3] < 0.
    {
        return Err(invalid(0));
    }
    let plan = plan(ctx, control)?;
    let (definition, mapping) = match &plan {
        ProductionDefinitionPlan::Definition(plan) => (plan, None),
        ProductionDefinitionPlan::Pattern { plan, mapping } => (plan, Some(*mapping)),
    };
    let actual = match &definition.descriptor {
        DefinitionDescriptor::Clip(_) => DefinitionKind::Clip,
        DefinitionDescriptor::Mask(_) => DefinitionKind::Mask,
        DefinitionDescriptor::Pattern(descriptor) => {
            if descriptor.definition != element {
                return Err(invalid(0));
            }
            let map = mapping.ok_or_else(|| invalid(0))?;
            map.pixel_inverse(*descriptor)?;
            let DefinitionTarget::Shape(shape) = owner.target else {
                return Err(invalid(0));
            };
            if ctx
                .builder
                .scene(ctx.scene)?
                .shape(shape)
                .ok_or_else(|| invalid(0))?
                .source
                != map.source_map
                || map.bounds != bounds
            {
                return Err(invalid(0));
            }
            DefinitionKind::Pattern
        }
        DefinitionDescriptor::Marker(_) => DefinitionKind::Marker,
        DefinitionDescriptor::Filter { filter, primitives } => {
            let DefinitionTarget::Group(_) = owner.target else {
                return Err(invalid(0));
            };
            crate::validate::filter(*filter, primitives, control)?;
            for p in primitives {
                control.charge(WorkKind::FilterPixel, 1).map_err(stopped)?;
                if p.source_offset > ctx.shared.source().len() {
                    return Err(invalid(p.source_offset));
                }
            }
            DefinitionKind::Filter
        }
    };
    if actual != kind || (kind != DefinitionKind::Pattern && mapping.is_some()) {
        return Err(invalid(0));
    }
    crate::mask_post::validate_production_post(ctx, kind, None, definition.post, control)?;
    if definition.expansions.len() > 65536 {
        return Err(crate::types::limit(LimitKind::References));
    }
    for expansion in &definition.expansions {
        crate::mask_post::validate_production_post(
            ctx,
            kind,
            Some(expansion.flavor),
            expansion.post,
            control,
        )?;
        control
            .charge(WorkKind::ReferenceProbe, 1)
            .map_err(stopped)?;
        expansion.range.require(ctx.shared.tokens().len(), 0)?;
        validate_style(ctx.shared.source(), &expansion.style, control)?;
        if !vexel_geometry::affine_valid(expansion.transform)
            || !expansion
                .viewport
                .into_iter()
                .all(|v| v.is_finite() && v > 0.)
        {
            return Err(invalid(0));
        }
    }
    control.checkpoint().map_err(stopped)?;
    Ok(plan)
}

fn validate_style(
    source: &[u8],
    style: &CssPaint<'_>,
    control: &mut dyn WorkControl,
) -> Result<()> {
    for property in vexel_svg_css::Property::ALL {
        control.charge(WorkKind::PaintVisit, 1).map_err(stopped)?;
        if let Some(value) = style.value(property) {
            let bytes = value
                .span
                .slice(source)
                .ok_or_else(|| invalid(value.span.offset))?;
            if bytes.as_ptr() != value.bytes.as_ptr() || bytes.len() != value.bytes.len() {
                return Err(invalid(value.span.offset));
            }
        }
    }
    Ok(())
}
//! Complete computed plan handoff. Mapping is carried at suspension, never
//! reconstructed by parsing source on resume. Original descriptors stay intact.
use crate::{
    types::{invalid, stopped},
    *,
};
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct PatternMapping {
    pub tile_origin: [f64; 2],
    pub user_to_base: Affine,
    pub pattern_transform: Affine,
    pub user_inverse: Affine,
    pub viewport: [f64; 2],
    pub bounds: [f64; 4],
    pub source_map: SourceMap,
    pub opacity: f64,
}
impl PatternMapping {
    pub fn pixel_inverse(self, descriptor: PatternDescriptor) -> Result<Affine> {
        use vexel_geometry::{affine_compose, affine_valid};
        if !self.tile_origin.into_iter().all(f64::is_finite)
            || !self.viewport.into_iter().all(|v| v.is_finite() && v > 0.)
            || !self.bounds.into_iter().all(f64::is_finite)
            || self.bounds[2] < 0.
            || self.bounds[3] < 0.
            || !self.opacity.is_finite()
            || !(0.0..=1.0).contains(&self.opacity)
            || !affine_valid(self.user_inverse)
            || !affine_valid(self.source_map.transform)
        {
            return Err(invalid(descriptor.error_offset));
        }
        // The supplied computed inverse must implement inverse(patternTransform)
        // followed by translation(-tileOrigin), as in the original algorithm.
        let back = affine_compose(self.user_to_base, self.pattern_transform)
            .ok_or_else(|| invalid(descriptor.error_offset))?;
        let expected = [1., 0., 0., 1., -self.tile_origin[0], -self.tile_origin[1]];
        for (a, b) in [back.a, back.b, back.c, back.d, back.e, back.f]
            .into_iter()
            .zip(expected)
        {
            if (a - b).abs() > 1e-9 * a.abs().max(b.abs()).max(1.) {
                return Err(invalid(descriptor.error_offset));
            }
        }
        let scale = Affine {
            a: descriptor.width as f64 / descriptor.tile_width,
            d: descriptor.height as f64 / descriptor.tile_height,
            b: 0.,
            c: 0.,
            e: 0.,
            f: 0.,
        };
        affine_compose(scale, self.user_to_base).ok_or_else(|| invalid(descriptor.error_offset))
    }
}
#[derive(Debug, Clone, Copy)]
pub(crate) struct PatternContinuation {
    mapping: PatternMapping,
    parent: SceneId,
    shape: ShapeId,
    channel: PaintChannel,
    draft: u64,
    generation: u64,
    request: Option<RequestToken>,
    job: LedgerIdentity,
}
impl PatternTickets {
    pub fn request_mapped<'a>(
        &mut self,
        builder: &'a SceneBuilder,
        draft: &DraftToken,
        source: &DecodeSource<'_>,
        child: SceneId,
        descriptor: PatternDescriptor,
        mapping: PatternMapping,
        shape: ShapeId,
        channel: PaintChannel,
        job: &RasterJob,
        control: &mut dyn WorkControl,
    ) -> Result<PatternRequest<'a>> {
        let i = builder.draft_index(draft)?;
        builder.draft_slot(draft, 3, shape.index(), builder.scenes[i].shapes.len())?;
        job.validate_source(builder.source_owner())?;
        if !std::sync::Arc::ptr_eq(builder.source_owner(), source.source_owner()) {
            return Err(invalid(0));
        }
        let definition = source.element(
            descriptor.definition,
            crate::memory::add(descriptor.definition.0, 1)?,
            control,
        )?;
        if definition.tokens()[descriptor.definition.0]
            .local_name
            .slice(source.source())
            != Some(b"pattern")
        {
            return Err(invalid(descriptor.error_offset));
        }
        let value = builder
            .scene(draft.mark.scene)?
            .shape(shape)
            .copied()
            .ok_or_else(|| invalid(0))?;
        if value.source != mapping.source_map
            || mapping
                .source_map
                .element
                .slice(builder.source_owner())
                .is_none()
        {
            return Err(invalid(0));
        }
        mapping.pixel_inverse(descriptor)?;
        let child_view = builder.scene(child)?;
        if child == draft.mark.scene || child.index() < draft.scene_count {
            return Err(invalid(0));
        }
        let request = self.request(child_view, descriptor, control)?;
        self.pending.as_mut().ok_or_else(|| invalid(0))?.production = Some(PatternContinuation {
            mapping,
            parent: draft.mark.scene,
            shape,
            channel,
            draft: draft.nonce,
            generation: builder.generation,
            request: builder.request_identity(),
            job: job.owner_identity(),
        });
        Ok(request)
    }
    /// Transfer admitted job output directly into the builder's owned pattern;
    /// then publish and attach the exact fill/stroke mapping. No raw Vec or Tile
    /// escapes this operation. Late errors unwind just this publication suffix.
    pub fn complete_mapped(
        &mut self,
        ticket: PatternTicket,
        builder: &mut SceneBuilder,
        draft: &DraftToken,
        job: &mut RasterJob,
        result: Result<JobRenderOutput>,
        control: &mut dyn WorkControl,
    ) -> Result<(PatternId, usize)> {
        let pending = self.pending.as_ref().ok_or_else(|| invalid(0))?;
        if pending.ticket != ticket {
            return Err(invalid(0));
        }
        let p = pending.production.ok_or_else(|| invalid(0))?;
        let descriptor = pending.descriptor;
        job.validate_source(builder.source_owner())?;
        if builder.owner != p.parent.owner || job.owner_identity() != p.job {
            return Err(invalid(0));
        }
        let child = pending.scene;
        let live = builder.draft_index(draft).is_ok()
            && draft.nonce == p.draft
            && draft.mark.scene == p.parent
            && builder.generation == p.generation
            && builder.request_identity() == p.request
            && builder
                .scene(child)
                .is_ok_and(|view| view.scene(child).is_some())
            && builder
                .scene(p.parent)
                .is_ok_and(|view| view.shape(p.shape).is_some());
        if !live {
            self.pending = None;
            if let Ok(output) = result {
                if output.validate(job).is_ok() {
                    job.release(output.pixels)?;
                }
            }
            return Err(invalid(0));
        }
        let output = match result {
            Ok(output) => output,
            Err(error) => {
                self.pending = None;
                return Err(error);
            }
        };
        output.validate(job)?;
        if output.width != descriptor.width
            || output.height != descriptor.height
            || output.generation != p.generation
        {
            return Err(invalid(0));
        }
        let inverse = p.mapping.pixel_inverse(descriptor)?;
        let mut shape = *builder
            .scene(p.parent)?
            .shape(p.shape)
            .ok_or_else(|| invalid(0))?;
        let i = builder.draft_index(draft)?;
        builder.draft_slot(draft, 3, p.shape.index(), builder.scenes[i].shapes.len())?;
        let mut mark = builder.checkpoint_internal(p.parent)?;
        let result = (|| {
            control.checkpoint().map_err(stopped)?;
            let id = job.publish_pattern_output(output, builder, p.parent, descriptor, control)?;
            let paint = Paint {
                kind: PaintKind::Pattern,
                spread: Spread::Repeat,
                object_bounding_box: false,
                coordinates: [
                    p.mapping.tile_origin[0],
                    p.mapping.tile_origin[1],
                    descriptor.tile_width,
                    descriptor.tile_height,
                    0.,
                    0.,
                ],
                bounds: p.mapping.bounds,
                user_inverse: p.mapping.user_inverse,
                gradient_inverse: vexel_geometry::affine_identity(),
                stops: TableRange::EMPTY,
                pattern: Some(id),
                pattern_inverse: inverse,
                pattern_opacity: p.mapping.opacity,
            };
            let index = match p.channel {
                PaintChannel::Fill => builder.append_fill_paint(p.parent, paint, control)?,
                PaintChannel::Stroke => builder.append_stroke_paint(p.parent, paint, control)?,
            };
            match p.channel {
                PaintChannel::Fill => shape.fill_paint = Some(index),
                PaintChannel::Stroke => shape.stroke_paint = Some(index),
            }
            builder.finalize_shape(draft, p.shape, shape, control)?;
            Ok((id, index))
        })();
        if result.is_err() {
            mark.epoch = builder.scenes[i].epoch;
            builder.rollback_internal(mark)?;
            // Output may not yet have transferred. Clean it unconditionally.
            if job.slice(output.pixels).is_ok() {
                job.release(output.pixels)?;
            }
        }
        self.pending = None;
        result
    }
}
//! Explicit production paint-channel handoff through real pattern publication.
mod support;
use support::*;
use std::sync::Arc;
use vexel_geometry::affine_identity as identity;
use vexel_scene::*;
use vexel_svg_css::Property;

fn element(doc: &LexicalDocument, name: &[u8]) -> ElementId {
    ElementId(doc.tokens().iter().position(|t| t.local_name.slice(doc.source()) == Some(name)).unwrap())
}

struct ChannelPlanner;
impl PaintChannelDefinitionPlanner for ChannelPlanner {
    fn plan_owned_pattern_definition<'src>(
        &mut self,
        ctx: &mut DefinitionContext<'src, '_>,
        element: ElementId,
        owner: DefinitionOwner,
        channel: PaintChannel,
        _: Affine,
        bounds: [f64; 4],
        style: &vexel_svg_css::CssPaint<'src>,
        _: &mut dyn WorkControl,
    ) -> Result<ProductionDefinitionPlan<'src>> {
        owner.validate(ctx)?;
        let property = match channel {
            PaintChannel::Fill => Property::FillOpacity,
            PaintChannel::Stroke => Property::StrokeOpacity,
        };
        let opacity = style.value(property).map_or(Ok(1.0), |value| {
            let bytes = value.span.slice(ctx.shared.source()).ok_or(Diagnostic {
                kind: ErrorKind::InvalidArgument,
                offset: value.span.offset,
            })?;
            std::str::from_utf8(bytes)
                .ok()
                .and_then(|value| value.parse::<f64>().ok())
                .ok_or(Diagnostic { kind: ErrorKind::InvalidArgument, offset: value.span.offset })
        })?;
        let DefinitionTarget::Shape(shape) = owner.target() else { unreachable!() };
        let source_map = ctx.builder.scene(ctx.scene)?.shape(shape).unwrap().source;
        let mapping = PatternMapping {
            tile_origin: [0., 0.], user_to_base: identity(), pattern_transform: identity(),
            user_inverse: identity(), viewport: [100., 100.], bounds, source_map, opacity,
        };
        let descriptor = PatternDescriptor {
            definition: element, width: 1, height: 1, tile_width: 1., tile_height: 1.,
            content_transform: identity(), error_offset: 0,
        };
        Ok(ProductionDefinitionPlan::Pattern {
            plan: DefinitionPlan {
                descriptor: DefinitionDescriptor::Pattern(descriptor),
                expansions: Vec::new(), post: PostOperation::None,
            },
            mapping,
        })
    }
}

