#[test]
fn both_production_routes_validate_distinct_host_owner_and_publish_real_definition() {
    for compatibility in [true, false] {
        let doc = LexicalDocument::parse(Arc::new(
            b"<svg><pattern/><filter/><path d=\"M0 0 L1 1 2 3 Z\"/></svg>".to_vec()),
            1 << 20, &mut Run).unwrap();
        let mut source = DecodeSource::new(&doc, &mut Run).unwrap();
        let mut builder = SceneBuilder::new(doc.source_owner().clone(), animation(doc.source_owner()),
            7, viewport(), Limits::default()).unwrap();
        let root = builder.root_id();
        let draft = builder.begin_draft(root).unwrap();
        let mut input = shape(doc.source());
        let start = doc.source().windows(5).position(|w| w == b"<path").unwrap();
        input.shape.source.element = Span { start, end: doc.source().len() - 6 };
        let shape_id = builder.append_shape(root, input, &mut Run).unwrap();
        let pattern = element(&doc, b"pattern");
        let host = element(&doc, b"path");
        assert_ne!(pattern, host);
        let owner = builder.definition_owner(&draft, &source, host,
            DefinitionTarget::Shape(shape_id), &mut Run).unwrap();
        assert_eq!(owner.element(), host);
        // An independently minted owner cannot authorize this builder, even
        // with the same source allocation and matching lexical anchor.
        let mut foreign_builder = SceneBuilder::new(doc.source_owner().clone(),
            animation(doc.source_owner()), 7, viewport(), Limits::default()).unwrap();
        let foreign_root = foreign_builder.root_id();
        let foreign_draft = foreign_builder.begin_draft(foreign_root).unwrap();
        let foreign_shape = foreign_builder.append_shape(foreign_root, shape(doc.source()), &mut Run).unwrap();
        let foreign_owner = foreign_builder.definition_owner(&foreign_draft, &source, host,
            DefinitionTarget::Shape(foreign_shape), &mut Run).unwrap();
        // Closing the owner's draft makes it stale even while its target lives.
        foreign_builder.commit_draft(&foreign_draft, &mut Run).unwrap();
        let next_draft = foreign_builder.begin_draft(foreign_root).unwrap();
        assert!(foreign_builder.definition_owner(&next_draft, &source, host,
            DefinitionTarget::Shape(shape_id), &mut Run).is_err());
        assert!(builder.definition_owner(&draft, &source, ElementId(usize::MAX),
            DefinitionTarget::Shape(shape_id), &mut Run).is_err());
        assert!(builder.definition_owner(&draft, &source, host,
            DefinitionTarget::Shape(foreign_shape), &mut Run).is_err());
        let style = source.compute_style(element(&doc, b"path"), None, &mut Run).unwrap();
        let mut active = ActiveDefinitions::default();
        let mut ledger = ChargeLedger::new(doc.source_owner(), 1 << 20, 65536).unwrap();
        let mut ctx = DefinitionContext { shared: &mut source, builder: &mut builder,
            scene: root, active: &mut active, ledger: &mut ledger };
        let mut planner = GuardPlanner { calls: 0 };
        let bounds = [0., 0., 10., 10.];
        let accounting_before = format!("{:?}", ctx.ledger);
        let scene_before = format!("{:?}", ctx.builder.scene(root).unwrap());
        macro_rules! dispatch {
            ($ctx:expr, $element:expr, $owner:expr, $bounds:expr, $control:expr) => {
                if compatibility {
                    plan_production_definition(&mut planner, $ctx, DefinitionKind::Pattern,
                        $element, $owner, identity(), $bounds, &style, $control)
                } else {
                    plan_production_pattern(&mut planner, $ctx, $element, $owner,
                        PaintChannel::Stroke, identity(), $bounds, &style, $control)
                }
            };
        }
        let invalid_element = dispatch!(&mut ctx, ElementId(doc.tokens().len() + 1), owner, bounds, &mut Run).unwrap_err();
        assert_eq!(invalid_element.kind, ErrorKind::InvalidArgument);
        assert_eq!(dispatch!(&mut ctx, pattern, foreign_owner, bounds, &mut Run).unwrap_err().kind,
            ErrorKind::InvalidArgument);
        let invalid_bounds = dispatch!(&mut ctx, pattern, owner, [0., 0., -1., 10.], &mut Run).unwrap_err();
        assert_eq!(invalid_bounds.kind, ErrorKind::InvalidArgument);
        assert_eq!(dispatch!(&mut ctx, pattern, owner, bounds, &mut CancelDispatch).unwrap_err().kind,
            ErrorKind::Canceled);
        let foreign_doc = LexicalDocument::parse(Arc::new(doc.source().to_vec()), 1 << 20, &mut Run).unwrap();
        let mut foreign_source = DecodeSource::new(&foreign_doc, &mut Run).unwrap();
        assert!(ctx.builder.definition_owner(&draft, &foreign_source, host,
            DefinitionTarget::Shape(shape_id), &mut Run).is_err());
        {
            let mut foreign_ctx = DefinitionContext { shared: &mut foreign_source,
                builder: ctx.builder, scene: root, active: ctx.active, ledger: ctx.ledger };
            assert_eq!(dispatch!(&mut foreign_ctx, pattern, owner, bounds, &mut Run).unwrap_err().kind,
                ErrorKind::InvalidArgument);
        }
        let foreign_scene_before = format!("{:?}", foreign_builder.scene(foreign_root).unwrap());
        {
            let mut stale_ctx = DefinitionContext { shared: ctx.shared,
                builder: &mut foreign_builder, scene: foreign_root, active: ctx.active, ledger: ctx.ledger };
            assert_eq!(dispatch!(&mut stale_ctx, pattern, foreign_owner, bounds, &mut Run).unwrap_err().kind,
                ErrorKind::InvalidArgument);
        }
        assert_eq!(format!("{:?}", foreign_builder.scene(foreign_root).unwrap()), foreign_scene_before);
        assert_eq!(planner.calls, 0);
        assert_eq!(format!("{:?}", ctx.ledger), accounting_before);
        assert_eq!(format!("{:?}", ctx.builder.scene(root).unwrap()), scene_before);
        let view = ctx.builder.scene(root).unwrap();
        assert_eq!(view.shapes.len(), 1);
        assert!(view.patterns.is_empty());
        assert!(view.fill_paints.is_empty());
        assert!(view.stroke_paints.is_empty());
        assert_eq!(view.shape(shape_id).unwrap().fill_paint, None);
        assert_eq!(view.shape(shape_id).unwrap().stroke_paint, None);
        let plan = if compatibility {
            plan_production_definition(&mut planner, &mut ctx, DefinitionKind::Pattern,
                pattern, owner, identity(), bounds, &style, &mut Run)
        } else {
            plan_production_pattern(&mut planner, &mut ctx, pattern, owner,
                PaintChannel::Stroke, identity(), bounds, &style, &mut Run)
        }.unwrap();
        assert_eq!(planner.calls, 1);
        let ProductionDefinitionPlan::Pattern { plan, mapping } = plan else { panic!("pattern expected") };
        let DefinitionDescriptor::Pattern(descriptor) = plan.descriptor else { panic!("descriptor expected") };
        assert_eq!(descriptor.definition, pattern);
        drop(ctx);
        let child = builder.new_scene(viewport()).unwrap();
        builder.seal(child, &mut Run).unwrap();
        let mut job = RasterJob::new(ChargeLedger::new(doc.source_owner(), 1 << 20, 65536).unwrap()).unwrap();
        let mut tickets = PatternTickets::new().unwrap();
        let channel = if compatibility { PaintChannel::Fill } else { PaintChannel::Stroke };
        let request = tickets.request_mapped(&builder, &draft, &source, child, descriptor,
            mapping, shape_id, channel, &job, &mut Run).unwrap();
        let pixels = job.buffer(RasterPool::Output, 16, &mut Run).unwrap();
        job.reserve(pixels, 4, &mut Run).unwrap();
        job.extend(pixels, &[4, 3, 2, 255], &mut Run).unwrap();
        let (id, index) = tickets.complete_mapped(request.ticket, &mut builder, &draft, &mut job,
            Ok(JobRenderOutput { generation: 7, pixels, width: 1, height: 1, stride: 4 }), &mut Run).unwrap();
        let view = builder.scene(root).unwrap();
        let paint = if compatibility { &view.fill_paints[index] } else { &view.stroke_paints[index] };
        assert_eq!(paint.pattern, Some(id));
        assert_eq!(view.pattern(id).unwrap().tile.rgba(), &[4, 3, 2, 255]);
        builder.commit_draft(&draft, &mut Run).unwrap();
        assert!(builder.freeze().is_ok());
    }
}

